new='''    private fun buildForegroundNotification(): Notification {\n        val playing = ::player.isInitialized && player.isPlaying\n        val builder = NotificationCompat.Builder(this, NOTIFICATION_CHANNEL_ID)\n            .setSmallIcon(if (playing) android.R.drawable.ic_media_pause else android.R.drawable.ic_media_play)\n            .setContentTitle(getCurrentTitle())\n            .setContentText(getCurrentArtist())\n            .setContentIntent(createOpenAppPendingIntent())\n            .setOngoing(true)\n            .setOnlyAlertOnce(true)\n            .setShowWhen(false)\n            .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)\n            .setCategory(NotificationCompat.CATEGORY_TRANSPORT)\n            .setPriority(NotificationCompat.PRIORITY_LOW)\n            .addAction(android.R.drawable.ic_media_previous, "قبلی", createServicePendingIntent(ACTION_PREVIOUS, 1003))\n            .addAction(android.R.drawable.ic_media_play, if (playing) "مکث" else "پخش", createServicePendingIntent(if (playing) ACTION_PAUSE else ACTION_PLAY, 1002))\n            .addAction(android.R.drawable.ic_media_next, "بعدی", createServicePendingIntent(ACTION_NEXT, 1004))\n            .addAction(android.R.drawable.ic_delete, "بستن", createServicePendingIntent(ACTION_STOP, 1005))\n            .addAction(android.R.drawable.ic_media_rew, "ولوم -", createServicePendingIntent(ACTION_VOLUME_DOWN, 1006))\n            .addAction(android.R.drawable.ic_media_ff, "ولوم +", createServicePendingIntent(ACTION_VOLUME_UP, 1007))\n\n        mediaSession?.let { session ->\n            builder.setStyle(\n                MediaStyle()\n                    .setMediaSession(session.sessionCompatToken)\n                    .setShowActionsInCompactView(0, 1, 2)\n            )\n        }\n        return builder.build()\n    }\n\n    private fun createServicePendingIntent(action: String, requestCode: Int): PendingIntent {\n        val intent = Intent(this, MusicService::class.java).apply { this.action = action }\n        return PendingIntent.getService(this, requestCode, intent, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)\n    }\n'''
