rep(svc, '''    private fun createMediaItem(url: String, title: String, artist: String, cover: String): MediaItem {\n        val metadata = MediaMetadata.Builder()\n            .setTitle(title.ifBlank { "Music Finder" })\n            .setArtist(artist.ifBlank { "Music Finder" })\n''', '''    private fun createMediaItem(\n        url: String,\n        title: String,\n        artist: String,\n        cover: String,\n        site: String = ""\n    ): MediaItem {\n        val metadata = MediaMetadata.Builder()\n            .setTitle(title.ifBlank { "Music Finder" })\n            .setArtist(artist.ifBlank { "Music Finder" })\n            .setExtras(Bundle().apply { putString("source_site", site) })\n''')

rep(svc, '''    private fun saveToHistory(item: MediaItem) {\n''', '''    private fun adjustSystemVolume(up: Boolean) {\n        try {\n            audioManager.adjustStreamVolume(\n                AudioManager.STREAM_MUSIC,\n                if (up) AudioManager.ADJUST_RAISE else AudioManager.ADJUST_LOWER,\n                0\n            )\n            player.volume = 1f\n            safeSendUpdate()\n            updateForegroundNotification()\n        } catch (_: Exception) { }\n    }\n\n    private fun loadAndPlayRelated() {\n        if (released || !::player.isInitialized) return\n        val item = player.currentMediaItem ?: return\n        val title = item.mediaMetadata.title?.toString() ?: return\n        val artist = item.mediaMetadata.artist?.toString() ?: ""\n        val oldUrl = item.mediaId\n        val site = item.mediaMetadata.extras?.getString("source_site") ?: ""\n\n        Thread {\n            val related = findRelatedFromSameSite(oldUrl, title, artist, site)\n            if (related.isEmpty()) return@Thread\n            Handler(Looper.getMainLooper()).post {\n                if (released || !::player.isInitialized) return@post\n                val current = player.currentMediaItem\n                if (current == null || current.mediaId != oldUrl || player.playbackState != Player.STATE_ENDED) return@post\n                try {\n                    player.setMediaItems(related.map { createMediaItem(it.url, it.title, it.artist, it.cover, it.site) }, 0, 0L)\n                    player.prepare()\n                    player.play()\n                    safeSendUpdate()\n                    updateForegroundNotification()\n                } catch (_: Exception) { }\n            }\n        }.start()\n    }\n\n    private fun findRelatedFromSameSite(currentUrl: String, currentTitle: String, currentArtist: String, siteName: String): List<SongResult> {\n        val domain = when (siteName.lowercase(Locale.ROOT)) {\n            "rozmusic" -> "rozmusic.com"\n            "bia2music" -> "mybia2music.com"\n            "musicdel" -> "musicdel.ir"\n            "musics-fa" -> "musics-fa.com"\n            else -> extractDomain(currentUrl)\n        }\n        if (domain.isBlank()) return emptyList()\n        return try {\n            val q = URLEncoder.encode("site:$domain ${currentArtist.ifBlank { currentTitle }} $currentTitle", "UTF-8")\n            val html = httpGet("https://www.google.com/search?q=$q&num=12") ?: return emptyList()\n            val urls = Regex("https?://[^\\\"'<> ]+")\n                .findAll(html).map { it.value.replace("\\\\u0026", "&") }\n                .filter { it.contains(domain, true) }.distinct().take(10).toList()\n            val out = ArrayList<SongResult>()\n            for (page in urls) {\n                val pageHtml = httpGet(page) ?: continue\n                val audio = Regex("https?://[^\\\"'<> ]+\\\\.(?:mp3|m4a|aac|ogg|wav|flac)(?:\\\\?[^\\\"'<> ]*)?", RegexOption.IGNORE_CASE).find(pageHtml)?.value ?: continue\n                if (audio == currentUrl || out.any { it.url == audio }) continue\n                val title = htmlMeta(pageHtml, "og:title").ifBlank { currentTitle }\n                val artist = htmlMeta(pageHtml, "music:musician").ifBlank { currentArtist }\n                val cover = htmlMeta(pageHtml, "og:image")\n                out.add(SongResult(audio, title, artist, siteName.ifBlank { domain }, cover))\n                if (out.size >= 5) break\n            }\n            out\n        } catch (_: Exception) { emptyList() }\n    }\n\n    private fun extractDomain(url: String): String = try { URL(url).host.removePrefix("www.") } catch (_: Exception) { "" }\n\n    private fun httpGet(url: String): String? {\n        var c: HttpURLConnection? = null\n        return try {\n            c = URL(url).openConnection() as HttpURLConnection\n            c.connectTimeout = 8000\n            c.readTimeout = 10000\n            c.instanceFollowRedirects = true\n            c.setRequestProperty("User-Agent", "Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36 Chrome/128 Mobile Safari/537.36")\n            if (c.responseCode !in 200..399) return null\n            c.inputStream.bufferedReader().use { it.readText() }\n        } catch (_: Exception) { null } finally { try { c?.disconnect() } catch (_: Exception) { } }\n    }\n\n    private fun htmlMeta(html: String, property: String): String {\n        val r = Regex("<meta[^>]+(?:property|name)=[\\\"']$property[\\\"'][^>]+content=[\\\"']([^\\\"']+)[\\\"'][^>]*>", RegexOption.IGNORE_CASE)\n        return r.find(html)?.groupValues?.getOrNull(1)?.trim() ?: ""\n    }\n\n    private fun saveToHistory(item: MediaItem) {\n''')

